// Table of a language; nullptr — unknown language.
inline const std::map<std::string, std::string>* messageTableOf(const std::string& lang) {
    if (lang == "ru") return &messageTable();
    if (lang == "en") return &messageTable_en();
    return nullptr;
}

// Interface languages: the source language first (app-ux §9.5).
inline const char* const MESSAGE_LANGUAGES[] = {"ru", "en"};

